Subject: [PATCH] libtaskmanager: add TasksModel::inlineGroupTasks()

When groups are shown inline, the group parent is filtered out of the
model, so a view has no way to find the other windows a task is grouped
with. This adds a helper that returns the indices of the whole group.

BUG: 415647
---
 libtaskmanager/tasksmodel.cpp | 26 ++++++++++++++++++++++++++
 libtaskmanager/tasksmodel.h   | 11 +++++++++++
 2 files changed, 37 insertions(+)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..b4cba2abff 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -1969,6 +1969,32 @@ QPersistentModelIndex TasksModel::makePersistentModelIndex(int row, int childCou
     return QPersistentModelIndex(makeModelIndex(row, childCount));
 }

+QModelIndexList TasksModel::inlineGroupTasks(const QModelIndex &index) const
+{
+    QModelIndexList tasks;
+
+    if (!d->flattenGroupsProxyModel || !index.isValid() || index.model() != this) {
+        return tasks;
+    }
+
+    const QModelIndex groupParent = d->flattenGroupsProxyModel->mapToSource(mapToSource(index)).parent();
+
+    if (!groupParent.isValid()) {
+        return tasks;
+    }
+
+    for (int i = 0; i < d->groupingProxyModel->rowCount(groupParent); ++i) {
+        const QModelIndex child = d->groupingProxyModel->index(i, 0, groupParent);
+        const QModelIndex task = mapFromSource(d->flattenGroupsProxyModel->mapFromSource(child));
+
+        if (task.isValid()) {
+            tasks.append(task);
+        }
+    }
+
+    return tasks;
+}
+
 void TasksModel::classBegin()
 {
     d->usedByQml = true;
diff --git a/libtaskmanager/tasksmodel.h b/libtaskmanager/tasksmodel.h
index 9cdad29325..7d329f386f 100644
--- a/libtaskmanager/tasksmodel.h
+++ b/libtaskmanager/tasksmodel.h
@@ -1014,6 +1014,17 @@ public:
      */
     Q_INVOKABLE QPersistentModelIndex makePersistentModelIndex(int row, int childRow = -1) const;

+    /**
+     * When groups are shown inline, returns the indices of all tasks that
+     * belong to the same group as the task at the given index, including
+     * itself. Returns an empty list if the task is not in an inline group.
+     *
+     * @param index An index in this tasks model.
+     * @returns a list of indices of the tasks in the inline group.
+     * @since 6.9
+     */
+    Q_INVOKABLE QModelIndexList inlineGroupTasks(const QModelIndex &index) const;
+
     void classBegin() override;
     void componentComplete() override;

